.ds-secondary:hover{background:var(--ds-tint)}.ds-secondary:active{background:rgba(207,224,214,.6)}
:host(.dark) .ds-secondary:active,:root.dark .ds-secondary:active,.ds-dark .ds-secondary:active{background:rgba(127,178,149,.28)}
.ds-secondary:disabled{opacity:.5;background:transparent}

.ds-modal-stage{padding:0}.ds-modal-backdrop{display:flex;align-items:center;justify-content:center;min-height:300px;padding:16px;background:rgba(11,17,32,.55);backdrop-filter:blur(4px)}
.ds-modal{position:relative;width:100%;max-width:448px;max-height:calc(100svh - 32px);overflow-y:auto;scroll-padding-top:24px;scroll-padding-bottom:24px;border:1px solid var(--ds-panel-line);border-radius:24px;background:var(--ds-panel);box-shadow:var(--ds-e5);outline:none;animation:ds-modal-in var(--duration-slow,600ms) var(--ease-standard,cubic-bezier(.4,0,.2,1))}
.ds-modal-header{display:flex;align-items:flex-start;gap:12px;padding:24px 24px 0}.ds-modal-header h2{min-width:0;flex:1;font-size:18px;line-height:28px;letter-spacing:0}
.ds-modal-close{flex:none;margin:-8px;padding:8px;border:0;border-radius:12px;background:transparent;color:var(--ds-muted);cursor:pointer;transition:color var(--duration-fast,150ms) var(--ease-standard,cubic-bezier(.4,0,.2,1))}
.ds-modal-close:hover{color:var(--ds-ink)}.ds-modal-close:focus-visible{outline:none;box-shadow:var(--ds-ring)}
.ds-modal-body{padding:16px 24px}.ds-modal-footer{display:flex;flex-direction:column;gap:8px;padding:8px 24px 24px}.ds-modal-footer .ds-button{width:100%}
@media(min-width:640px){.ds-modal-footer{flex-direction:row;justify-content:flex-end}.ds-modal-footer .ds-button{width:auto}}
@keyframes ds-modal-in{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}@media(prefers-reduced-motion:reduce){.ds-modal{animation:none}}
